CREATE TABLE ALLOCATION (ALLOCATIONID BIGINT NOT NULL, ALLOCSTATUS VARCHAR(255), ALLOCTYPE VARCHAR(255), ALLOCATIONPRICE DECIMAL(15), AVERAGEPRCGRPID BIGINT, AVERAGEPRICE DECIMAL(15), CLEARINGMECHANISM VARCHAR(255), CLIENTSSI BIGINT, COMMISSION DECIMAL(15), COMMISSIONAMOUNT DECIMAL(15), COMMISSIONTYPE VARCHAR(255), EXCHANGEID BIGINT, FIRMDEPO BIGINT, INSTRUMENTID BIGINT, PAYMENTMETHOD VARCHAR(255), QUANTITY DECIMAL(15), SETTLEDATE INTEGER, SUBACCOUNTID BIGINT, TOPACCOUNTID BIGINT, TRADEDATE INTEGER, "VERSION" INTEGER, PRIMARY KEY (ALLOCATIONID))
