CREATE TABLE FILL (FILLID BIGINT NOT NULL, CAPACITY VARCHAR(255), EXCHANGEID BIGINT, EXECUTEDSHARES DECIMAL(15), EXECUTIONTIME TIME, EXTERNALREF VARCHAR(255), INSTRUMENTID BIGINT, ISOFFMARKET SMALLINT DEFAULT 0, ORDERID BIGINT, PRICE DECIMAL(15), SIDE VARCHAR(255), TRADEDATE INTEGER, "VERSION" INTEGER, PRIMARY KEY (FILLID))
CREATE TABLE ORDERS (ORDERID BIGINT NOT NULL, AVERAGEPRCGRPID BIGINT, BOOKID BIGINT, CAPACITY VARCHAR(255), CLIENTID BIGINT, COMMISSION DECIMAL(15), COMMISSIONTYPE VARCHAR(255), CURRENCY VARCHAR(255), EXCHANGEID BIGINT, EXECUTIONCOUNTRY VARCHAR(255), EXECUTIONREGION VARCHAR(255), FLOWTYPE VARCHAR(255), FOORDERREF VARCHAR(255), FRONTOFFICECOMMENT DECIMAL(15), FXDIRECTION VARCHAR(255), FXRATE DECIMAL(15), INSTRUMENTID BIGINT, MOCOMMENT VARCHAR(255), ORDERSTATUS VARCHAR(255), PORTFOLIOID BIGINT, QUANTITY DECIMAL(15), SALESID VARCHAR(255), SETTLECONVERSION VARCHAR(255), SETTLECURRENCY VARCHAR(255), SETTLEDATE INTEGER, SIDE VARCHAR(255), TRADEDATE INTEGER, TRADERID VARCHAR(255), "VERSION" INTEGER, PRIMARY KEY (ORDERID))
CREATE TABLE PORTFOLIO (PORTFOLIOID BIGINT NOT NULL, NAME VARCHAR(255), TRADEDATE INTEGER, PRIMARY KEY (PORTFOLIOID))
CREATE TABLE TASK (TASKID BIGINT NOT NULL, ASSIGNEDGROUP VARCHAR(255), ASSIGNEDUSER VARCHAR(255), COMMENTS VARCHAR(255), CREATIONTIME TIME, DESCRIPTION VARCHAR(255), MODIFIEDTIME TIME, OBJECTID BIGINT, OBJECTTYPE VARCHAR(255), PRIORITY VARCHAR(255), TASKSTATUS VARCHAR(255), TASKTYPE VARCHAR(255), TRADEDATE INTEGER, "VERSION" INTEGER, PRIMARY KEY (TASKID))
